window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[175]={"id":"175","numero":175,"titre":"Voyage en pays tropical de l'enfant et de l'adulte","objectifs":[{"id":"175-1","rang":"A","rubrique":"Définition","titre":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","contenu":"<p>L'évaluation pré-voyage repose sur <strong>3 paramètres</strong> à croiser systématiquement pour estimer le risque sanitaire individuel.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Éléments à analyser</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Destination</strong></td>\n            <td>Situation <span class=\"kw-def\">sanitaire et politique</span> du pays ; saison ; zones visitées (<span class=\"kw-clinique\">rurales</span> ou <span class=\"kw-clinique\">urbaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Voyage</strong></td>\n            <td><strong>Modalités :</strong> moyen de transport ; conditions de logement ; activités prévues (baignade, randonnée) ; voyage organisé ou aventureux<br>\n            <strong>Durée :</strong> une exposition <span class=\"kw-clinique\">ponctuelle</span> suffit pour le <span class=\"kw-etio\">paludisme</span> (anophèle), la <span class=\"kw-etio\">fièvre jaune</span> et la <span class=\"kw-etio\">dengue</span> (Aedes), le <span class=\"kw-etio\">VIH</span> (<span class=\"kw-def\">contact</span> sexuel) ; une exposition <span class=\"kw-clinique\">prolongée</span> est nécessaire pour la <span class=\"kw-etio\">lèpre</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">filarioses</span></td>\n          </tr>\n          <tr>\n            <td><strong>Voyageur</strong></td>\n            <td>Âge ; <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-def\">comorbidités</span> ; statut <span class=\"kw-def\">immunitaire et vaccinal</span> ; budget — vaccins et <span class=\"kw-def\">chimioprophylaxie</span> <strong>non remboursés</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Voyageurs particulièrement à risque :</strong></p>\n      <ul>\n        <li>Adultes jeunes en <span class=\"kw-clinique\">voyage non organisé</span> vers certaines destinations (Afrique subsaharienne, Inde), sur plusieurs semaines</li>\n        <li>Sujets <span class=\"kw-clinique\">émigrés</span> effectuant un séjour dans leur pays d'origine</li>\n        <li><span class=\"kw-alerte\">Immunodéprimés</span></li>\n      </ul>\n      <p><strong>Sources numériques d'information :</strong> <span class=\"kw-clinique\">les</span> recommandations aux voyageurs sont émises par le <span class=\"kw-def\">Comité des maladies liées aux voyages et des maladies d'importation (CMVI)</span> du HCSP, publiées dans le <span class=\"kw-def\">Bulletin épidémiologique hebdomadaire (BEH)</span> et actualisées selon la situation internationale.</p>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Mortalité</span> du voyageur.</strong> <span class=\"kw-clinique\">Les</span> causes <strong>non infectieuses</strong> dominent : <span class=\"kw-alerte\">pathologies cardio-vasculaires</span> (&gt;<span class=\"kw-chiffre\"> 50 %</span> des décès), traumatologie. Les pathologies infectieuses ne représentent que <span class=\"kw-chiffre\">1-3 %</span> des décès — par ordre de fréquence : <span class=\"kw-clinique\">diarrhée</span> ++ &gt; infections des voies aériennes supérieures &gt; dermatoses &gt; infections systémiques (<span class=\"kw-clinique\">paludisme</span>).</div>","frequence":2},{"id":"175-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","contenu":"<p><span class=\"kw-clinique\">Les</span> conseils de prévention, donnés en <strong>consultation pré-voyage</strong>, se déclinent par domaine d'exposition.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Conseils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Maladie chronique</strong></td>\n            <td>Évaluation avant le départ ; partir avec des documents médicaux (en anglais si besoin) ; le voyage peut être <span class=\"kw-ci\">contre-indiqué</span> selon <span class=\"kw-clinique\">les</span> cas</td>\n          </tr>\n          <tr>\n            <td><strong>Hygiène alimentaire</strong></td>\n            <td>Prévient <span class=\"kw-clinique\">les</span> maladies à transmission <span class=\"kw-def\">oro-fécale</span> (<span class=\"kw-etio\">turista</span>, <span class=\"kw-etio\">typhoïde</span>, <span class=\"kw-etio\">VHA</span>, <span class=\"kw-etio\">VHE</span>, parasitoses intestinales) :<br>\n            • lavage des mains après les toilettes et avant les repas (SHA en l'absence de point d'eau)<br>\n            • eau en bouteille encapsulée, ou rendue potable (filtration, ébullition, désinfectant)<br>\n            • lait pasteurisé ou bouilli ; viande et poisson bien cuits, consommés chauds<br>\n            • peler les fruits ; éviter crudités, coquillages, buffets froids, glaçons et glaces<br>\n            • se méfier de la <span class=\"kw-alerte\">ciguatera</span> (toxicité des gros poissons de mer)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention sexuelle</strong></td>\n            <td>Préservatif conseillé ; en cas de conduite sexuelle à risque, consulter au plus tôt (<span class=\"kw-chiffre\">&lt; 24 h</span>) pour un éventuel <span class=\"kw-ttt\">traitement post-exposition</span></td>\n          </tr>\n          <tr>\n            <td><strong>Protection anti-vectorielle</strong></td>\n            <td>Vêtements longs, moustiquaire, répulsifs, insecticides. Vecteurs :<br>\n            • <span class=\"kw-etio\">Anophèle</span> (pique la <strong>nuit</strong>) → <span class=\"kw-clinique\">paludisme</span><br>\n            • <span class=\"kw-etio\">Culex</span> (pique la <strong>nuit</strong>) → rickettsioses, borrélioses, encéphalites à tiques<br>\n            • <span class=\"kw-etio\">Aedes</span> (pique le <strong>jour</strong>) → dengue, zika, chikungunya, <span class=\"kw-clinique\">fièvre</span> jaune</td>\n          </tr>\n          <tr>\n            <td><strong>Baignade et sol</strong></td>\n            <td>Pas de baignade en eau douce stagnante (<span class=\"kw-etio\">schistosomoses</span>, <span class=\"kw-etio\">leptospirose</span>) ; ne pas marcher pieds nus en extérieur (<span class=\"kw-etio\">anguillulose</span>, <span class=\"kw-etio\">ankylostomose</span>) ; ne pas s'allonger sur le sable de certaines plages des Antilles ; repasser au fer chaud le linge séché au soleil (<span class=\"kw-etio\">myiase</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Soleil et chaleur</strong></td>\n            <td>Pas d'<span class=\"kw-etio\">exposition solaire</span> avant l'âge de <span class=\"kw-chiffre\">1 an</span> ; crème solaire <span class=\"kw-chiffre\">FPS ≥ 30</span> réappliquée toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 h</span> ; lunettes enveloppantes à verres filtrants <span class=\"kw-chiffre\">CE 3 ou 4</span></td>\n          </tr>\n          <tr>\n            <td><strong>Animaux</strong></td>\n            <td>Chaussures fermées et pantalons longs en végétation dense ; secouer habits, draps, sacs de couchage et chaussures (scorpions, serpents) ; ne pas approcher <span class=\"kw-clinique\">les</span> animaux errants (<span class=\"kw-etio\">rage</span>) ; éviter les volailles en Asie du Sud-Est (<span class=\"kw-etio\">grippe aviaire</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Trousse du voyageur</strong> (l'antipaludique préventif et <span class=\"kw-clinique\">les</span> répulsifs ne sont <span class=\"kw-clinique\">pas remboursés</span>) :</p>\n      <ul>\n        <li><strong>Anti-vectoriel :</strong> répulsifs contre <span class=\"kw-clinique\">les</span> arthropodes ; antipaludique à usage préventif si nécessaire</li>\n        <li><strong>Médicaments :</strong> <span class=\"kw-ttt\">paracétamol</span> (<span class=\"kw-ttt\">antalgique</span> / antipyrétique) ; <span class=\"kw-ttt\">racécadotril</span> (antidiarrhéique antisécrétoire) ; antiémétique ; antibiotique en l'absence de soins locaux ; <span class=\"kw-ttt\">anti-H1</span> de dernière génération</li>\n        <li><strong>Autres produits :</strong> SHA ; produit de désinfection de l'eau de boisson ; <span class=\"kw-ttt\">soluté de réhydratation orale</span> ; écran solaire 50+ ; sérum physiologique monodose ; antiseptique, pansements et sutures adhésives ; bande de contention, thermomètre, pince à épiler, préservatifs, masques</li>\n        <li><strong>Ordonnance :</strong> traitement habituel rédigé en <span class=\"kw-def\">DCI</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Chimioprophylaxie</span> antipaludique (rappel).</strong> Toujours en association à la protection anti-vectorielle ; <span class=\"kw-clinique\">non remboursée</span> et <strong>ne protège pas à<span class=\"kw-chiffre\"> 100 %</span></strong>. Molécules recommandées pour l'Afrique subsaharienne :\n        <ul>\n          <li><span class=\"kw-ttt\">Atovaquone-proguanil</span> : prise <strong>durant le séjour</strong>, quotidienne, poursuivie <span class=\"kw-chiffre\">1 semaine</span> après le retour (agit sur <span class=\"kw-clinique\">les</span> <strong>formes hépatiques</strong>, d'où la durée réduite) ; dès <span class=\"kw-chiffre\">≥ 11 kg</span></li>\n          <li><span class=\"kw-ttt\">Méfloquine</span> : début <span class=\"kw-chiffre\">10 jours</span> avant le départ (test de tolérance, demi-vie longue), prise hebdomadaire, poursuivie <span class=\"kw-chiffre\">3 semaines</span> après le retour ; dès <span class=\"kw-chiffre\">≥ 15 kg</span> — <span class=\"kw-ci\">CI : ATCD de dépression, ATCD de convulsion, prise de valproate de sodium</span></li>\n          <li><span class=\"kw-ttt\">Doxycycline</span> : prise <strong>durant le séjour</strong>, quotidienne, poursuivie <span class=\"kw-chiffre\">4 semaines</span> après le retour ; dès <span class=\"kw-chiffre\">≥ 8 ans</span></li>\n        </ul>\n        Mises à jour chaque année dans le <span class=\"kw-def\">BEH</span> (HCSP). <em>📎 cf. item 170 — <span class=\"kw-clinique\">Paludisme</span></em> pour le détail complet.</div>","frequence":1},{"id":"175-3","rang":"A","rubrique":"Prise en charge","titre":"Identifier les personnes avec une fragilité particulière","contenu":"<p>Certains profils imposent une <strong>évaluation pré-voyage renforcée</strong> : adaptation des vaccins et de la <span class=\"kw-def\">chimioprophylaxie</span>, voire <span class=\"kw-ci\">contre-indication</span> du voyage.</p>\n      <table >\n        <thead><tr><th>Profil fragile</th><th>Enjeu spécifique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Immunodéprimé</span></td>\n            <td>Vaccins <span class=\"kw-ci\">vivants atténués contre-indiqués</span> (anti-amarile possible dans le <span class=\"kw-etio\">VIH</span> si <span class=\"kw-bio\">CD4</span> <span class=\"kw-chiffre\">&gt; 200/mm³</span> et <span class=\"kw-chiffre\">&gt; 15 %</span> de <span class=\"kw-bio\">lymphocytes</span>) ; risque <span class=\"kw-etio\">infectieux</span> majoré</td>\n          </tr>\n          <tr>\n            <td><strong>Femme enceinte</strong></td>\n            <td>Vaccin <span class=\"kw-ci\">anti-amarile déconseillé</span> ; <span class=\"kw-etio\">paludisme</span> volontiers grave ; certains antipaludiques et répulsifs limités</td>\n          </tr>\n          <tr>\n            <td><strong>Jeune enfant / nourrisson</strong></td>\n            <td>BHE immature → <span class=\"kw-ci\">pas de répulsif cutané avant 6 mois</span> ; pas d'<span class=\"kw-etio\">exposition solaire</span> avant <span class=\"kw-chiffre\">1 an</span> ; vaccins soumis à un âge minimal</td>\n          </tr>\n          <tr>\n            <td><strong>Sujet âgé</strong></td>\n            <td><span class=\"kw-def\">Comorbidités</span> ; <span class=\"kw-ttt\">vaccin antigrippal</span> recommandé au-delà de <span class=\"kw-chiffre\">65 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Maladie chronique</strong></td>\n            <td>Évaluation de la stabilité de la pathologie ; documents médicaux ; voyage parfois <span class=\"kw-ci\">contre-indiqué</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sujet émigré</strong> retournant au pays d'origine</td>\n            <td>Moindre recours à la prévention ; perte d'immunité ; séjours souvent longs, en zone rurale</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Pour ces profils, l'évaluation pré-voyage est renforcée et le voyage peut être déconseillé voire <span class=\"kw-ci\">contre-indiqué</span>.</div>","frequence":0},{"id":"175-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales infections acquises au cours d’un voyage en zone tropicale","contenu":"<p><span class=\"kw-clinique\">Les</span> pathologies infectieuses du voyageur se répartissent, <strong>par ordre de fréquence</strong> : 1. pathologies <span class=\"kw-clinique\">digestives</span> (<span class=\"kw-clinique\">diarrhée</span> ++) ; 2. infections des voies aériennes supérieures ; 3. <span class=\"kw-clinique\">dermatoses</span> ; 4. infections systémiques (<span class=\"kw-etio\">paludisme</span>).</p>\n      <p>Chaque <strong>vecteur</strong> oriente vers un groupe de pathologies :</p>\n      <table >\n        <thead><tr><th>Vecteur</th><th>Pathologies associées</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Tique</span></td><td>Borréliose de Lyme ; <span class=\"kw-clinique\">fièvre</span> boutonneuse méditerranéenne (<em>Rickettsia conorii</em>) ; <span class=\"kw-etio\">encéphalite</span> à tiques ; tularémie</td></tr>\n          <tr><td><span class=\"kw-etio\">Poux</span></td><td>Typhus épidémique (<em>Rickettsia prowazekii</em>) ; <span class=\"kw-clinique\">fièvre</span> des tranchées (<em>Bartonella quintana</em>) ; <span class=\"kw-clinique\">fièvre</span> récurrente (<em>Borrelia recurrentis</em>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Aedes</span></td><td>Dengue ; <span class=\"kw-clinique\">fièvre</span> jaune ; chikungunya ; zika</td></tr>\n          <tr><td><span class=\"kw-etio\">Anophèle</span></td><td><span class=\"kw-clinique\">Paludisme</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Phlébotome</span></td><td>Leishmaniose</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 167 — Hépatites virales · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"175-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les vaccinations spécifiques du voyageur","contenu":"<p>La <span class=\"kw-ttt\">vaccination</span> du voyageur combine <strong>3 catégories</strong> : mise à jour des vaccins de routine, vaccins <strong>obl<span class=\"kw-chiffre\">iga</span>toires</strong>, vaccins <strong>recommandés</strong>. Vaccins et <span class=\"kw-def\">chimioprophylaxie</span> ne sont <span class=\"kw-clinique\">pas remboursés</span>.</p>\n      <p><strong>Vaccins de routine</strong></p>\n      <ul>\n        <li>Mise à jour du <span class=\"kw-def\">calendrier vaccinal</span> avant le départ</li>\n        <li>Chez l'enfant non vacciné, en cas de séjour prolongé (<span class=\"kw-chiffre\">&gt; 1 mois</span>) en pays de forte endémie : <span class=\"kw-ttt\">BCG</span> ; vaccin <span class=\"kw-ttt\">anti-rougeoleux</span> (dès <span class=\"kw-chiffre\">6 mois</span>, vaccin monovalent) ; vaccin contre l'<span class=\"kw-ttt\">hépatite B</span></li>\n        <li>Vaccin <span class=\"kw-ttt\">antigrippal</span> : voyageurs de <span class=\"kw-chiffre\">&gt; 65 ans</span>, personnels nav<span class=\"kw-chiffre\">iga</span>nts et guides accompagnant un groupe (vaccin adapté à l'hémisphère sud disponible uniquement en ATU nominative)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Vaccins obl<span class=\"kw-chiffre\">iga</span>toires.</strong>\n        <strong><span class=\"kw-clinique\">Fièvre</span> jaune (anti-amarile) :</strong> vaccin <span class=\"kw-def\">vivant atténué</span> ; <span class=\"kw-ci\">CI grossesse</span> (déconseillé) et <span class=\"kw-ci\">immunodéprimé</span> (possible dans le <span class=\"kw-etio\">VIH</span> si <span class=\"kw-bio\">CD4</span> <span class=\"kw-chiffre\">&gt; 200/mm³</span> et <span class=\"kw-chiffre\">&gt; 15 %</span> de <span class=\"kw-bio\">lymphocytes</span>) ; obligatoire ou recommandé pour l'Afrique intertropicale et la région amazonienne, <span class=\"kw-alerte\">absent en Asie et en Océanie</span> ; authentifié par un médecin d'un Centre agréé de Vaccinations Internationales sur le carnet international ; efficace <span class=\"kw-chiffre\">10 jours</span> après l'injection et pour <strong>toute la vie</strong> (sauf injection avant <span class=\"kw-chiffre\">2 ans</span> ou pendant la <span class=\"kw-ci\">grossesse</span>).<br>\n        <strong><span class=\"kw-etio\">Méningocoque</span> ACYW conjugué :</strong> obligatoire pour le <strong>pèlerinage en Arabie Saoudite</strong>.</div>\n      <p><strong>Vaccins recommandés</strong></p>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Type · âge</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Hépatite B</span></td><td>Vaccin inerte (protéines recombinantes)</td><td>Séjour fréquent ou prolongé en zone d'endémie</td></tr>\n          <tr><td><span class=\"kw-ttt\">Hépatite A</span></td><td>Vaccin inerte ; dès <span class=\"kw-chiffre\">≥ 1 an</span></td><td>Séjour en pays à hygiène précaire, <strong>quelles que soient <span class=\"kw-clinique\">les</span> conditions du séjour</strong></td></tr>\n          <tr><td><span class=\"kw-ttt\">Typhoïde</span></td><td>Vaccin <span class=\"kw-def\">polyosidique</span> ; efficacité <span class=\"kw-chiffre\">60 %</span> ; rappel tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> ; dès <span class=\"kw-chiffre\">≥ 2 ans</span></td><td>Séjours prolongés en pays à bas niveau d'hygiène (sous-continent indien ++)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Rage</span> (pré-exposition)</td><td>Vaccin inerte ; dès l'âge de la marche</td><td>Séjour prolongé, aventureux ou isolé en zone à risque (Asie, Afrique, Amérique du Sud)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Méningocoque ACYW</span></td><td>Conjugué</td><td>Ceinture de la <span class=\"kw-etio\">méningite</span> en Afrique en saison sèche (<span class=\"kw-chiffre\">novembre-juin</span>) ; <span class=\"kw-def\">contact</span> étroit et prolongé avec la population</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Vaccins de l'enfant voyageur</strong> — âge minimal et régions :</p>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Âge minimal</th><th>Régions / commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span> jaune</td><td><span class=\"kw-chiffre\">9 mois</span> (<span class=\"kw-chiffre\">6 mois</span> si épidémie)</td><td>Régions intertropicales d'Afrique et d'Amérique du Sud ; <span class=\"kw-ci\">CI immunodéprimé</span>, <span class=\"kw-ci\">allergie</span> à l'œuf</td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite</span> A</td><td><span class=\"kw-chiffre\">1 an</span></td><td>Toutes destinations tropicales ou peu hygiéniques — à proposer largement</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningocoque</span> ACYW</td><td><span class=\"kw-chiffre\">1 an</span></td><td>Afrique subsaharienne en saison sèche</td></tr>\n          <tr><td>Rage</td><td>Dès l'âge de la marche</td><td>Asie, Amérique du Sud, Afrique ; séjour isolé ou prolongé</td></tr>\n          <tr><td>Typhoïde</td><td><span class=\"kw-chiffre\">2 ans</span></td><td>Sous-continent indien, Asie du Sud-Est, Afrique ; protection limitée (<span class=\"kw-chiffre\">60-80 %</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Encéphalite</span> japonaise</td><td><span class=\"kw-chiffre\">2 mois</span></td><td>Asie du Sud-Est, sous-continent indien ; activités extérieures près des rizières à la saison des pluies</td></tr>\n          <tr><td><span class=\"kw-etio\">Encéphalite</span> à tiques</td><td><span class=\"kw-chiffre\">1 an</span></td><td>Europe centrale, orientale et septentrionale ; du printemps à novembre</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Rang C</strong> (pour mémoire) : <span class=\"kw-ttt\">choléra</span> (personnel de santé en période d'épidémie) ; <span class=\"kw-ttt\">encéphalite japonaise</span> ; <span class=\"kw-ttt\">encéphalite à tiques</span>.</p>\n      <div class=\"callout callout-info\"><strong>Mnémo.</strong> « Pas de <span class=\"kw-clinique\">fièvre</span> jaune chez <span class=\"kw-clinique\">les</span> jaunes » — le vaccin anti-amarile ne concerne <strong>pas</strong> l'Asie ni l'Océanie, où la <span class=\"kw-clinique\">fièvre</span> jaune est absente.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":6},{"id":"175-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les indications d’une sérologie hépatite A chez un patient à risque d’exposition antérieure","contenu":"<p>Le <span class=\"kw-etio\">VHA</span> est une <span class=\"kw-def\">maladie immunisante</span> : un sujet ayant déjà contracté l'<span class=\"kw-etio\">hépatite</span> A est protégé à vie. La <span class=\"kw-bio\">sérologie VHA</span> permet d'identifier <span class=\"kw-clinique\">les</span> patients <strong>déjà immunisés</strong>, à qui une <span class=\"kw-ttt\">vaccination</span> serait inutile.</p>\n      <p>Indications d'une <span class=\"kw-bio\">sérologie VHA</span> <strong>avant de décider de vacciner</strong> (recherche d'une <span class=\"kw-def\">immunité ancienne</span>, chez un patient à risque d'exposition antérieure) :</p>\n      <ul>\n        <li>Personnes <strong>nées en France avant 1945</strong> (<span class=\"kw-chiffre\">&gt; 75 ans</span>)</li>\n        <li>Personnes ayant <strong>vécu dans un pays d'endémie</strong></li>\n        <li>Personnes signalant un <strong>antécédent d'<span class=\"kw-clinique\">ictère</span></strong></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p>","frequence":0},{"id":"175-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les conseils de prévention vis-à-vis des parasitoses à transmission éco-orale ou transcutanée","contenu":"<p><span class=\"kw-clinique\">Les</span> parasitoses du voyageur se préviennent selon leur <strong>voie de transmission</strong> — deux mécanismes distincts.</p>\n      <div class=\"callout callout-info\"><strong>Transmission éco-orale</strong> (mains, eau, aliments souillés). Concerne <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">parasitoses intestinales</span> (<span class=\"kw-etio\">protozooses</span>, helminthoses). Prévention : lavage des mains, eau encapsulée ou traitée, éviter les crudités et aliments souillés, peler les fruits.</div>\n      <div class=\"callout callout-info\"><strong>Transmission transcutanée</strong> (pénétration active de la larve à travers la peau). Prévention :\n        <ul>\n          <li>Pas de baignade en eau douce → <span class=\"kw-etio\">schistosomoses</span></li>\n          <li>Ne pas marcher pieds nus en extérieur → <span class=\"kw-etio\">anguillulose (strongyloïdose)</span>, <span class=\"kw-etio\">ankylostomose</span> (<span class=\"kw-etio\">larva migrans cutanée</span>)</li>\n          <li>Ne pas s'allonger directement sur le sable contaminé de certaines plages → <span class=\"kw-etio\">ankylostomose</span></li>\n          <li>Repasser au fer chaud le linge séché au soleil → <span class=\"kw-etio\">myiase</span></li>\n        </ul>\n      </div>","frequence":1},{"id":"175-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales maladies d’importation responsables de fièvre","contenu":"<p>Devant une <span class=\"kw-clinique\">fièvre</span> au retour des tropiques, un petit nombre de <strong>maladies d'importation</strong> concentre l'essentiel des diagnostics. Chacune a une orientation clinico-<span class=\"kw-ttt\">biologique</span> propre.</p>\n      <table >\n        <thead><tr><th>Maladie</th><th>Contamination</th><th>Orientation clinique</th><th>Biologie</th><th>Confirmation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Paludisme</span></strong></td>\n            <td>Anophèle</td>\n            <td>Troubles digestifs et neurologiques ; <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">hépatomégalie</span></td>\n            <td><span class=\"kw-bio\">Thrombopénie</span> ++ ; anémie ; leucopénie ; <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">ALAT</span> &lt; 5N</td>\n            <td><span class=\"kw-bio\">Goutte épaisse</span> + frottis mince ; TDR ; biologie moléculaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Arboviroses</span></strong> (dengue ++)</td>\n            <td>Aedes</td>\n            <td><span class=\"kw-clinique\">Myalgies</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">rash</span>, <span class=\"kw-clinique\">splénomégalie</span></td>\n            <td>Leucopénie ++ ; thrombopénie ++ ; <span class=\"kw-bio\">CRP</span> basse ; <span class=\"kw-bio\">ALAT</span> &lt; 5N</td>\n            <td><span class=\"kw-bio\">PCR</span> durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premiers jours</span> de <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-bio\">sérologie</span> au-delà</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hépatites virales</span></strong></td>\n            <td>Oro-fécale (<span class=\"kw-etio\">VHA</span>)</td>\n            <td>Troubles digestifs ; <span class=\"kw-clinique\">ictère</span> ; <span class=\"kw-clinique\">hépatomégalie</span> ; <span class=\"kw-clinique\">urticaire</span></td>\n            <td>Leucopénie ; <span class=\"kw-bio\">CRP</span> basse ; <span class=\"kw-bio\">ALAT &gt; 10N</span></td>\n            <td><span class=\"kw-bio\">Sérologies</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Fièvre typhoïde</span></strong></td>\n            <td>Oro-fécale (réservoir strictement humain)</td>\n            <td><span class=\"kw-clinique\">Céphalées</span> ++ ; insomnie ; <span class=\"kw-clinique\">pouls dissocié</span> ; <span class=\"kw-clinique\">splénomégalie</span></td>\n            <td>Leucopénie ; <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">ALAT</span> &lt; 5N</td>\n            <td><span class=\"kw-bio\">Hémocultures</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Rickettsioses</span></strong></td>\n            <td>Tiques</td>\n            <td><span class=\"kw-clinique\">Escarre d'inoculation</span> ; <span class=\"kw-clinique\">éruption</span> ; <span class=\"kw-clinique\">adénopathies</span> ; <span class=\"kw-clinique\">céphalées</span></td>\n            <td>Leucopénie ; thrombopénie ; <span class=\"kw-bio\">CRP</span> élevée</td>\n            <td><span class=\"kw-bio\">Sérologies</span> ; <span class=\"kw-bio\">biopsie</span> cutanée puis <span class=\"kw-bio\">PCR</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Amoebose hépatique</span></strong></td>\n            <td>Oro-fécale</td>\n            <td><span class=\"kw-clinique\">Hépatomégalie douloureuse</span></td>\n            <td><span class=\"kw-bio\">Hyperleucocytose à PNN</span> ; <span class=\"kw-bio\">CRP</span> élevée</td>\n            <td><span class=\"kw-imagerie\">Échographie</span> hépatique ± <span class=\"kw-imagerie\">TDM</span> ; <span class=\"kw-bio\">sérologie</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Schistosomose</span></strong> (phase d'invasion)</td>\n            <td>Baignade en eau douce</td>\n            <td><span class=\"kw-clinique\">Prurit</span>, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">hépatomégalie</span>, <span class=\"kw-clinique\">toux</span></td>\n            <td><span class=\"kw-bio\">Hyperéosinophilie</span> ; <span class=\"kw-bio\">CRP</span> élevée</td>\n            <td><span class=\"kw-bio\">Sérologie</span> en phase d'invasion ; recherche d'œufs (selles, urines) en phase d'état</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe n°1.</strong> Le <span class=\"kw-alerte\">paludisme à <em>P. falciparum</em></span> est la 1ʳᵉ cause à évoquer devant toute <span class=\"kw-clinique\">fièvre</span> survenant dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant le retour d'une zone d'endémie. La <span class=\"kw-etio\">dengue</span> est la 2ᵉ étiologie la plus fréquente.</div>\n      <div class=\"callout callout-warn\"><strong>Ne pas oublier.</strong> Une <span class=\"kw-clinique\">fièvre</span> au retour peut être <strong>non infectieuse</strong> (MTEV, néoplasie, maladie <span class=\"kw-etio\">inflammatoire</span>) ou infectieuse <strong>cosmopolite</strong> (PNA, <span class=\"kw-etio\">grippe</span>, pneumopathie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":0},{"id":"175-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","contenu":"<p>La démarche est systématique : devant toute <span class=\"kw-clinique\">fièvre</span> au retour, <strong>l'<span class=\"kw-alerte\">urgence</span> est d'éliminer un <span class=\"kw-clinique\">paludisme</span></strong>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>Destination précise ; dates du séjour ; <span class=\"kw-def\">durée d'incubation</span> ; <span class=\"kw-ttt\">chimioprophylaxie</span> antipaludique suivie ou non ; statut vaccinal ; activités à risque (baignade, <span class=\"kw-def\">contact</span> animal, rapports)</td>\n          </tr>\n          <tr>\n            <td><strong>Réflexe n°1</strong></td>\n            <td>Éliminer en <span class=\"kw-alerte\">urgence</span> un <span class=\"kw-etio\">paludisme à <em>P. falciparum</em></span> : <span class=\"kw-bio\">frottis-goutte épaisse</span> + <span class=\"kw-bio\">TDR</span> sans délai — <span class=\"kw-alerte\">urgence</span> diagnostique <strong>et</strong> thérapeutique</td>\n          </tr>\n          <tr>\n            <td><strong>Bilan <span class=\"kw-ttt\">biologique</span></strong></td>\n            <td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">transaminases</span> ; <span class=\"kw-bio\">hémocultures</span> ; <span class=\"kw-bio\">sérologies</span> orientées par la clinique</td>\n          </tr>\n          <tr>\n            <td><strong>Élargir</strong></td>\n            <td>Penser aux causes <strong>non infectieuses</strong> (MTEV, néoplasie, maladie <span class=\"kw-etio\">inflammatoire</span>) et infectieuses <strong>cosmopolites</strong> (PNA, <span class=\"kw-etio\">grippe</span>, pneumopathie)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Règle absolue.</strong> Toute <span class=\"kw-clinique\">fièvre</span> au retour des tropiques est un <span class=\"kw-alerte\">paludisme jusqu'à preuve du contraire</span> — le frottis-<span class=\"kw-bio\">goutte épaisse</span> prime sur tout autre examen.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 190 — <span class=\"kw-clinique\">Fièvre</span> prolongée</em></p>","frequence":2},{"id":"175-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les signes d’orientation étiologiques en fonction des durées d’incubation","contenu":"<p>La <strong>durée d'incubation</strong> (intervalle entre l'exposition et l'apparition de la <span class=\"kw-clinique\">fièvre</span>) restreint fortement le champ étiologique.</p>\n      <table >\n        <thead><tr><th>Incubation</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 7 jours</span></strong></td>\n            <td><strong>Diarrhées infectieuses :</strong> shigellose ; choléra ; salmonelloses non typhiques<br><strong>Arboviroses :</strong> dengue ; zika ; chikungunya</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">7-14 jours</span></strong></td>\n            <td><span class=\"kw-etio\">Paludisme à <em>P. falciparum</em></span> ; <span class=\"kw-etio\">typhoïde</span> ; spirochétoses (leptospirose, borrélioses) ; rickettsioses</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 2 semaines</span></strong></td>\n            <td><span class=\"kw-clinique\">Paludisme</span> à <em><span class=\"kw-clinique\">P. falciparum</span></em> (jusqu'à<span class=\"kw-chiffre\"> 2 mois</span>) ; typhoïde (jusqu'à<span class=\"kw-chiffre\"> 3 semaines</span>) ; hépatites A, B et E ; <span class=\"kw-etio\">primo-infection VIH</span> (<span class=\"kw-chiffre\">2-8 semaines</span>) ; schistosomose en phase d'invasion (<span class=\"kw-chiffre\">2-6 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mois à années</strong></td>\n            <td>Trypanosomoses ; leishmaniose viscérale ; <span class=\"kw-clinique\">paludisme</span> à <em>P. non falciparum</em> ; <span class=\"kw-etio\">amoebose hépatique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'amoebose intestinale aiguë ne donne <strong>pas</strong> de <span class=\"kw-clinique\">fièvre</span> — seule l'amoebose <strong>hépatique</strong> est fébrile.</div>","frequence":0},{"id":"175-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités d’analyse de la courbe thermique en cas de fièvre au retour du voyage","contenu":"<p>L'<strong>allure de la courbe thermique</strong> et <span class=\"kw-clinique\">les</span> signes cliniques associés affinent l'orientation étiologique.</p>\n      <table >\n        <thead><tr><th>Profil thermique</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Fièvre</span> récurrente</strong> (accès fébriles répétés)</td><td><span class=\"kw-etio\">Paludisme</span> ; <span class=\"kw-etio\">borréliose</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Fièvre</span> en plateau</strong></td><td><span class=\"kw-etio\">Typhoïde</span> au 3ᵉ septénaire ; viroses (dengue, chikungunya, <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span>) ; schistosomose</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Fièvre</span> + signes hémorragiques</strong></td><td><span class=\"kw-clinique\">Paludisme</span> ; <span class=\"kw-etio\">hépatite</span> fulminante ; leptospirose ictéro-<span class=\"kw-etio\">hémorragique</span> ; dengue et arboviroses hémorragiques ; <span class=\"kw-alerte\">fièvres hémorragiques virales</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>signes cliniques associés</strong> orientent également :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Ictère</span> :</strong> <span class=\"kw-etio\">hépatite</span> aiguë ; <span class=\"kw-clinique\">paludisme</span> ; leptospirose</li>\n        <li><strong><span class=\"kw-clinique\">Hépatomégalie</span> :</strong> typhoïde ; <span class=\"kw-etio\">hépatite</span> aiguë ; <span class=\"kw-clinique\">paludisme</span> ; amoebose ; schistosomose</li>\n        <li><strong><span class=\"kw-clinique\">Splénomégalie</span> :</strong> <span class=\"kw-clinique\">paludisme</span> ; brucellose ; typhoïde ; dengue</li>\n      </ul>","frequence":1},{"id":"175-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une fièvre hémorragique virale","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">fièvres hémorragiques virales (FHV)</span> sont rares mais d'une gravité extrême et hautement contagieuses.</p>\n      <ul>\n        <li><strong>Virus :</strong> <span class=\"kw-etio\">Ebola</span>, <span class=\"kw-etio\">Marburg</span>, <span class=\"kw-etio\">Lassa</span> — ce ne sont <strong>pas</strong> des arboviroses</li>\n        <li><strong>Présentation :</strong> <span class=\"kw-clinique\">fièvre</span> associée à un <span class=\"kw-alerte\">syndrome hémorragique</span> au retour d'une zone à risque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Conduite à tenir.</strong> Toute suspicion de FHV impose des <span class=\"kw-alerte\">précautions complémentaires</span> renforcées pour la protection du patient <strong>et</strong> du personnel : <span class=\"kw-def\">isolement</span> et <span class=\"kw-def\">signalement</span> immédiats. La prise en charge est guidée par le <span class=\"kw-def\">Centre National de Référence (CNR) des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span> — <span class=\"kw-clinique\">les</span> contacter avant tout prélèvement.</div>","frequence":0},{"id":"175-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la typhoïde","contenu":"<p>La <span class=\"kw-etio\">fièvre typhoïde</span> est une infection systémique à transmission oro-fécale, à <strong>déclaration obl<span class=\"kw-chiffre\">iga</span>toire</strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Germe</strong></td><td><span class=\"kw-etio\">Salmonella enterica</span> sérotypes Typhi et Paratyphi A, B ou C ; <strong>réservoir strictement humain</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Physiopathologie</span></strong></td><td>Franchissement de la barrière intestinale sans la léser → circulation sanguine via le système lymphatique → lyse <span class=\"kw-etio\">bactérienne</span> libérant une <span class=\"kw-def\">endotoxine</span> responsable des manifestations viscérales</td></tr>\n          <tr><td><strong>Incubation</strong></td><td><span class=\"kw-chiffre\">10 jours à 3 semaines</span></td></tr>\n          <tr><td><strong>Phase d'invasion</strong> (<span class=\"kw-chiffre\">1 semaine</span>)</td><td><span class=\"kw-clinique\">Fièvre</span> progressivement croissante ; <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">céphalées</span>, insomnie ; <span class=\"kw-clinique\">pouls dissocié</span> ; <span class=\"kw-clinique\">splénomégalie</span> (<span class=\"kw-chiffre\">30 %</span>) ; troubles digestifs</td></tr>\n          <tr><td><strong>Phase d'état</strong></td><td><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-clinique\">en plateau</span> à<span class=\"kw-chiffre\"> 40 °C</span> ; pouls dissocié ; <span class=\"kw-clinique\">tuphos</span> (inversion du rythme nycthéméral, prostration, <span class=\"kw-clinique\">obnubilation</span>) ; <span class=\"kw-clinique\">diarrhée « jus de melon »</span> (2/3 des cas) ; exanthème lenticulaire roséoliforme du tronc (1/3) ; <span class=\"kw-clinique\">angine de Duguet</span> (ulcérations des piliers antérieurs et du voile du palais,<span class=\"kw-chiffre\"> 10 %</span>)</td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">Leuco-neutropénie</span> ; <span class=\"kw-bio\">CRP élevée</span></td></tr>\n          <tr><td><strong>Confirmation</strong></td><td><span class=\"kw-bio\">Hémocultures</span></td></tr>\n          <tr><td><strong>Complications</strong></td><td><strong>Digestives :</strong> <span class=\"kw-alerte\">hémorragies digestives</span> ; <span class=\"kw-alerte\">perforations digestives</span><br><strong>Toxiniques :</strong> myocardite ; <span class=\"kw-etio\">encéphalite</span><br><strong>Septiques :</strong> localisations septiques secondaires</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La <span class=\"kw-clinique\">fièvre</span> typhoïde est une <strong>maladie à déclaration obl<span class=\"kw-chiffre\">iga</span>toire</strong> ; le traitement repose sur une C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> parentérale en probabiliste, secondairement adaptée à l'<span class=\"kw-bio\">antibiogramme</span>.</div>","frequence":0},{"id":"175-14","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies des diarrhées d’importation","contenu":"<p><span class=\"kw-clinique\">Les</span> diarrhées d'importation se classent selon la présence ou non de <strong><span class=\"kw-clinique\">fièvre</span></strong>.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Diarrhée</span> fébrile</strong> (souvent aiguë)</td>\n            <td><span class=\"kw-etio\">Turista</span> ; <span class=\"kw-etio\">paludisme</span> (à évoquer en premier, surtout chez l'enfant) ; shigellose, salmonelloses, <em><span class=\"kw-etio\">Campylobacter</span></em> si <span class=\"kw-clinique\">syndrome dysentérique</span> (<span class=\"kw-bio\">coproculture</span>) ; <span class=\"kw-etio\">primo-infection VIH</span> ; hépatites A et E ; <em>Clostridioides difficile</em> en cas d'ATB récente</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Diarrhée</span> non fébrile</strong> (souvent subaiguë)</td>\n            <td><span class=\"kw-clinique\">Paludisme</span> (<span class=\"kw-chiffre\">10 %</span> de présentations atypiques) ; <span class=\"kw-etio\">choléra</span> ; helminthoses intestinales (orientées par l'<span class=\"kw-bio\">hyperéosinophilie</span>) ; <span class=\"kw-etio\">protozooses</span> le plus souvent : <span class=\"kw-etio\">giardose</span> (cause la plus fréquente de <span class=\"kw-clinique\">diarrhée</span> prolongée non fébrile au retour des tropiques), amoebose intestinale aiguë, cyclosporose</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Diarrhée</span> médicamenteuse</strong></td>\n            <td><span class=\"kw-ttt\">AINS</span> ; antipaludiques (<span class=\"kw-ttt\">atovaquone-proguanil</span>, chloroquine-proguanil)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges.</strong> Le <span class=\"kw-clinique\">paludisme</span> peut se présenter comme une <span class=\"kw-clinique\">diarrhée</span> <strong>non fébrile</strong> atypique. L'amoebose intestinale aiguë ne donne <strong>pas</strong> de <span class=\"kw-clinique\">fièvre</span>, alors que l'amoebose <strong>hépatique</strong> peut donner des diarrhées fébriles.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span></em></p>","frequence":0},{"id":"175-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","contenu":"<p>La <span class=\"kw-etio\">diarrhée du voyageur (turista)</span> est extrêmement fréquente mais rarement grave.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Délai</strong></td><td>Survient souvent la <span class=\"kw-chiffre\">1ʳᵉ semaine</span> du séjour ; guérison spontanée en <span class=\"kw-chiffre\">3-5 jours</span></td></tr>\n          <tr>\n            <td><strong>Germes</strong></td>\n            <td><strong>Bactéries (<span class=\"kw-chiffre\">50 %</span>) :</strong> <span class=\"kw-etio\">E. coli entérotoxinogène (ETEC)</span> au 1ᵉʳ plan ; <span class=\"kw-etio\">E. coli</span> entéro-invasif ; <span class=\"kw-etio\">Salmonella</span><br><strong>Virus (<span class=\"kw-chiffre\">5-25 %</span>) :</strong> <span class=\"kw-etio\">norovirus</span><br><strong>Parasites (&lt;<span class=\"kw-chiffre\"> 10 %</span>) :</strong> protozoaires, amibes</td>\n          </tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span class=\"kw-ttt\">Réhydratation</span> dans tous <span class=\"kw-clinique\">les</span> cas (SRO chez l'enfant) ; <span class=\"kw-ttt\">racécadotril</span> (antidiarrhéique antisécrétoire) si nécessaire ; <span class=\"kw-ttt\">antibiothérapie</span> <strong>non recommandée en routine</strong></td></tr>\n          <tr><td><strong>Indications d'ATB</strong></td><td><span class=\"kw-ttt\">Azithromycine</span> en 1ʳᵉ intention (ou <span class=\"kw-ttt\">ciprofloxacine</span>), <span class=\"kw-chiffre\">1 à 5 jours</span> — uniquement si <span class=\"kw-clinique\">diarrhée</span> invasive, ou <span class=\"kw-clinique\">diarrhée</span> cholériforme intense persistant <span class=\"kw-chiffre\">&gt; 48 h</span> sans recours possible aux soins locaux</td></tr>\n        </tbody>\n      </table>\n      <p>Devant une suspicion de <strong>protozoose</strong> (<span class=\"kw-clinique\">diarrhée</span> prolongée) :</p>\n      <ol>\n        <li><span class=\"kw-bio\">Examen parasitologique des selles</span></li>\n        <li>Si difficile : <span class=\"kw-ttt\">traitement d'épreuve</span> par nitro-imidazolé (<span class=\"kw-ttt\">métronidazole</span>)</li>\n        <li>Si échec : <span class=\"kw-imagerie\">coloscopie</span> parfois nécessaire</li>\n      </ol>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique</em></p>","frequence":1},{"id":"175-16","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir évoquer puis confirmer le diagnostic des parasitoses intestinales","contenu":"<p>Le diagnostic des parasitoses intestinales suit deux temps : <strong>évoquer</strong>, puis <strong>confirmer</strong>.</p>\n      <p><strong>Évoquer</strong> devant :</p>\n      <ul>\n        <li>Une <span class=\"kw-clinique\">diarrhée prolongée non fébrile</span> au retour des tropiques (<span class=\"kw-etio\">giardose</span> ++)</li>\n        <li>Une <span class=\"kw-bio\">hyperéosinophilie</span> sanguine → oriente vers une <span class=\"kw-etio\">helminthose</span></li>\n        <li>Un contexte d'exposition (baignade en eau douce → <span class=\"kw-etio\">schistosomose</span>)</li>\n      </ul>\n      <p><strong>Confirmer</strong> par :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Examen parasitologique des selles</span> (à répéter) — recherche de kystes, œufs ou larves</li>\n        <li><span class=\"kw-bio\">Sérologie</span>, utile notamment en phase précoce</li>\n        <li><span class=\"kw-ttt\">Traitement d'épreuve</span> par <span class=\"kw-ttt\">métronidazole</span> si l'<span class=\"kw-bio\">EPS</span> n'est pas contributif</li>\n        <li><span class=\"kw-imagerie\">Endoscopie</span> (rectos<span class=\"kw-chiffre\">igm</span>oïdoscopie) en dernier recours</li>\n      </ul>\n      <p>Principales <span class=\"kw-etio\">protozooses</span> intestinales : <span class=\"kw-etio\">giardose</span>, <span class=\"kw-etio\">amoebose à <em>Entamoeba histolytica</em></span>, <span class=\"kw-etio\">cyclosporose</span> — traitement par <span class=\"kw-ttt\">métronidazole</span> pour l'amoebose.</p>","frequence":0},{"id":"175-17","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription des recherches parasitologiques dans des contextes évocateurs (schistosomoses, helminthoses digestives, protozooses digestives)","contenu":"<p><span class=\"kw-clinique\">Les</span> recherches parasitologiques se prescrivent dans un <strong>contexte évocateur</strong> (exposition, symptômes, hyperéosinophilie) et selon le parasite suspecté.</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Modalités de prescription</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Schistosomoses</span></strong></td>\n            <td><strong>Phase d'invasion :</strong> <span class=\"kw-bio\">sérologie</span><br><strong>Phase d'état :</strong> recherche d'œufs par microscopie ou <span class=\"kw-bio\">TAAN</span> sur <span class=\"kw-clinique\">urines 3 jours de suite</span>, <span class=\"kw-clinique\">selles</span>, et <span class=\"kw-clinique\">biopsies par voie endoscopique</span> (vessie, rectum)</td>\n          </tr>\n          <tr>\n            <td><strong>Helminthoses digestives</strong></td>\n            <td><span class=\"kw-bio\">Examen parasitologique des selles</span> ; recherche d'une <span class=\"kw-bio\">hyperéosinophilie</span> sanguine d'orientation</td>\n          </tr>\n          <tr>\n            <td><strong>Protozooses digestives</strong></td>\n            <td><span class=\"kw-bio\">Examen parasitologique des selles</span> répété (giardose, amoebose, cyclosporose) ; <span class=\"kw-bio\">TAAN</span> dans certains cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie</em></p>","frequence":0},{"id":"175-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de lésion cutanée au retour du voyage","contenu":"<p>Devant une <strong><span class=\"kw-clinique\">lésion</span> cutanée au retour d'un voyage</strong>, le type de lésion élémentaire oriente le diagnostic.</p>\n      <table >\n        <thead><tr><th>Type de lésion</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Exanthème fébrile</span></strong></td><td><span class=\"kw-etio\">Primo-infection VIH</span> ; arboviroses (dengue, chikungunya, zika) ; rickettsiose ; leptospirose ; <span class=\"kw-ci\">allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Escarre d'inoculation</span></strong></td><td><span class=\"kw-etio\">Rickettsiose</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Lésions urticariennes</span></strong></td><td><span class=\"kw-etio\">Schistosomose</span> en phase d'invasion ; <span class=\"kw-etio\">hépatite</span> <span class=\"kw-etio\">virale</span> en phase pré-ictérique ; <span class=\"kw-ci\">allergie</span> médicamenteuse</td></tr>\n          <tr><td><strong>Maladies tropicales localisées à la peau</strong></td><td><span class=\"kw-etio\">Leishmaniose cutanée</span> (<span class=\"kw-clinique\">ulcération</span> d'<span class=\"kw-clinique\">évolution</span> chronique, lésion nodulaire) ; <span class=\"kw-etio\">larva migrans cutanée</span> ankylostomienne ; <span class=\"kw-etio\">myiase</span> (nodules non nécrotiques) ; <span class=\"kw-clinique\">prurigo</span> après piqûre d'insecte</td></tr>\n        </tbody>\n      </table>","frequence":4},{"id":"175-19","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales dermatoses d’importation","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>dermatoses d'importation</strong> se reconnaissent au type de <span class=\"kw-clinique\">lésion</span> élémentaire.</p>\n      <table >\n        <thead><tr><th>Lésion</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Œdème</span></strong></td><td><strong>Membres :</strong> <span class=\"kw-etio\">dermohypodermite bactérienne</span> (<span class=\"kw-etio\">streptocoque</span> du groupe A, <em>S. aureus</em>) ; <span class=\"kw-etio\">loase</span> ; filarioses lymphatiques<br><strong>Face :</strong> <span class=\"kw-etio\">trichinellose</span> ; <span class=\"kw-etio\">maladie de Chagas</span></td></tr>\n          <tr><td><strong>Nodules</strong></td><td><strong>Nécrotiques :</strong> <span class=\"kw-etio\">furoncle</span> (<em>S. aureus</em>)<br><strong>Non nécrotiques :</strong> <span class=\"kw-etio\">myiase</span> ; <span class=\"kw-etio\">tungose</span> (puces-chiques)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Ulcération</span></strong></td><td>Ecthyma (<span class=\"kw-etio\">streptocoque</span> A, <em>S. aureus</em>) ; <span class=\"kw-etio\">charbon</span> ; trypanosome ; <span class=\"kw-etio\">ulcère de Buruli</span> ; <span class=\"kw-etio\">leishmaniose</span> (<span class=\"kw-clinique\">évolution</span> chronique)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Lésion</span> nodulaire</strong></td><td><span class=\"kw-etio\">Leishmaniose</span> ; <span class=\"kw-etio\">mycobactéries atypiques</span> ; <span class=\"kw-etio\">sporotrichose</span></td></tr>\n          <tr><td><strong>Exanthème</strong></td><td><strong>Urticarien :</strong> invasions helminthiques (schistosomose, <span class=\"kw-etio\">syndrome de Löffler</span>), filariose, <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span><br><strong>Maculopapuleux :</strong> arboviroses ; primo-infection VIH ; rickettsioses ; <span class=\"kw-etio\">syphilis</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Prurit</span> diffus</strong></td><td><span class=\"kw-etio\">Gale</span> ; piqûres d'arthropodes ; <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">onchocercose</span> ; <span class=\"kw-clinique\">dermatite</span> des nageurs</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Larva migrans cutanée</span></strong></td><td>Larbish (ankylostomes du chien ou du chat) ; larva currens (<span class=\"kw-etio\">strongyloïdose</span> ; Asie du Sud-Est, Mexique)</td></tr>\n        </tbody>\n      </table>\n      <p>Quelques dermatoses d'importation typiques :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/dengue-exantheme.png\" alt=\"Exanthème maculeux diffus de l'abdomen au cours d'une dengue\" loading=\"lazy\">\n        <figcaption>Dengue — exanthème maculeux diffus, signe cutané fréquent des arboviroses fébriles. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/larva-migrans-pied.png\" alt=\"Larva migrans cutanée de la plante du pied — cordon serpigineux érythémateux\" loading=\"lazy\">\n        <figcaption>Larva migrans cutanée du pied chez un enfant de <span class=\"kw-chiffre\">9 ans</span> (Brésil) — cordon serpigineux prurigineux dû à la migration sous-cutanée d'une larve d'ankylostome. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/myiase-extraction.png\" alt=\"Larve de Dermatobia hominis après extraction d'un nodule cutané de myiase\" loading=\"lazy\">\n        <figcaption>Myiase à <em>Dermatobia hominis</em> — larve après extraction du <span class=\"kw-clinique\">nodule</span> cutané. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/175/myiase-nodule.png\" alt=\"Lésion nodulaire pseudo-pustuleuse d'une myiase cutanée\" loading=\"lazy\">\n        <figcaption>Myiase — <span class=\"kw-clinique\">lésion</span> nodulaire pseudo-pustuleuse, non nécrotique. Source : fiche source EDN item 175 — Voyage en pays tropical (Pilly étudiant 2023).</figcaption>\n      </figure>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Paludisme</span> à <em><span class=\"kw-clinique\">P. falciparum</span></em> — réflexe n°1</strong></p><p><span class=\"kw-bio\">frottis mince</span> + <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">TDR</span> <strong>sans délai</strong> — <span class=\"kw-alerte\">urgence diagnostique ET thérapeutique</span> (cf. item 170)</p><ul><li>1ʳᵉ cause à évoquer devant toute <span class=\"kw-clinique\">fièvre</span> survenant dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant le retour d’une zone d’endémie</li></ul><p><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> suspectée</strong></p><p><span class=\"kw-alerte\">isolement et signalement immédiats</span> ; <span class=\"kw-ttt\">précautions complémentaires</span> renforcées (patient ET personnel) ; contacter le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span> <strong>avant tout prélèvement</strong></p><p><strong><span class=\"kw-etio\">Dengue</span> — fenêtre <span class=\"kw-bio\">PCR</span></strong></p><p><span class=\"kw-bio\">PCR</span> positive uniquement durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premiers jours</span> de <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-bio\">sérologie</span> au-delà</p><p><strong>Exposition sexuelle à risque</strong></p><p>consulter au plus tôt (<span class=\"kw-chiffre\">&lt; 24 h</span>) pour un éventuel <span class=\"kw-ttt\">traitement post-exposition</span></p>","hospit":"<p><strong><span class=\"kw-clinique\">Paludisme</span> à <em><span class=\"kw-clinique\">P. falciparum</span></em> confirmé :</strong> prise en charge en <span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique ; recherche des <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et traitement spécifique — <em>cf. item 170 (Paludisme)</em>.<br><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> suspectée :</strong> <span class=\"kw-alerte\">isolement immédiat</span> et <span class=\"kw-ttt\">précautions complémentaires</span>, orientation guidée par le <span class=\"kw-def\">CNR</span> et <span class=\"kw-def\">Santé publique France</span>.<br><strong><span class=\"kw-etio\">Fièvre typhoïde</span> :</strong> infection systémique relevant d’une <span class=\"kw-ttt\">antibiothérapie parentérale</span> (<span class=\"kw-ttt\">C3G</span>) ; <span class=\"kw-alerte\">maladie à déclaration obligatoire</span>.<br><strong><span class=\"kw-etio\">Turista</span> :</strong> prise en charge <span class=\"kw-clinique\">ambulatoire</span> (rarement grave), centrée sur la <span class=\"kw-ttt\">réhydratation</span> ; <span class=\"kw-alerte\">hospitalisation</span> réservée aux formes sévères ou au <span class=\"kw-def\">terrain</span> fragile.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-alerte\">signes hémorragiques</span> → évoquer <span class=\"kw-etio\">fièvre hémorragique virale</span> (<span class=\"kw-etio\">Ebola</span>, <span class=\"kw-etio\">Marburg</span>, <span class=\"kw-etio\">Lassa</span>), <span class=\"kw-etio\">paludisme</span>, <span class=\"kw-etio\">dengue</span> <span class=\"kw-etio\">hémorragique</span>, <span class=\"kw-etio\">leptospirose</span> ictéro-hémorragique, <span class=\"kw-etio\">hépatite</span> fulminante, <span class=\"kw-etio\">fièvre jaune</span></li><li><span class=\"kw-etio\">Fièvre jaune</span> : <span class=\"kw-alerte\">insuffisance hépatocellulaire et rénale</span> avec <span class=\"kw-alerte\">syndrome hémorragique</span> — <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20 %</span></li><li><span class=\"kw-etio\">Arbovirose</span> se compliquant d’<span class=\"kw-alerte\">hémorragies</span> et/ou d’<span class=\"kw-alerte\">encéphalite</span></li><li><span class=\"kw-etio\">Dengue</span> <span class=\"kw-etio\">hémorragique</span> / <span class=\"kw-alerte\">choc</span> (1 cas / 1 000)</li><li><span class=\"kw-etio\">Fièvre typhoïde</span> compliquée : <span class=\"kw-alerte\">hémorragies digestives</span>, <span class=\"kw-alerte\">perforations digestives</span>, <span class=\"kw-alerte\">myocardite</span>, <span class=\"kw-alerte\">encéphalite</span></li><li><span class=\"kw-clinique\">Ictère</span> fébrile → <span class=\"kw-etio\">hépatite</span> aiguë, <span class=\"kw-etio\">paludisme</span>, <span class=\"kw-etio\">leptospirose</span></li><li><span class=\"kw-def\">Terrain</span> à risque de forme grave : <span class=\"kw-alerte\">immunodéprimé</span>, <span class=\"kw-alerte\">femme enceinte</span>, <span class=\"kw-alerte\">jeune enfant</span> (<span class=\"kw-etio\">paludisme</span> à évoquer en 1ᵉʳ)</li></ul>","principes":"<p>Après élimination du <span class=\"kw-etio\">paludisme</span>, la prise en charge est <strong>étiologique</strong> : <span class=\"kw-ttt\">réhydratation</span> de la <span class=\"kw-etio\">turista</span>, <span class=\"kw-ttt\">antibiothérapie</span> ciblée des bactérioses (typhoïde), <span class=\"kw-ttt\">antiparasitaires</span> (schistosomose, amoebose, protozooses), traitement <strong>symptomatique</strong> des arboviroses.</p><p><strong><span class=\"kw-etio\">Turista</span> (<span class=\"kw-clinique\">diarrhée</span> du voyageur)</strong></p><ul><li><span class=\"kw-ttt\">Réhydratation</span> dans tous <span class=\"kw-clinique\">les</span> cas (<span class=\"kw-ttt\">SRO</span> chez l’enfant)</li><li><span class=\"kw-ttt\">Racécadotril</span> (antidiarrhéique antisécrétoire) si nécessaire</li><li><span class=\"kw-ttt\">Antibiothérapie</span> <strong>non recommandée en routine</strong></li><li><span class=\"kw-ttt\">Azithromycine</span> en 1ʳᵉ intention (ou <span class=\"kw-ttt\">ciprofloxacine</span>), <span class=\"kw-chiffre\">1 à 5 jours</span> — uniquement si <span class=\"kw-clinique\">diarrhée</span> invasive, ou cholériforme intense persistant <span class=\"kw-chiffre\">&gt; 48 h</span> sans recours possible aux soins locaux</li></ul><p><strong><span class=\"kw-clinique\">Diarrhée</span> prolongée / <span class=\"kw-etio\">protozoose</span></strong></p><ul><li>1. <span class=\"kw-bio\">Examen parasitologique des selles</span></li><li>2. Si difficile : <span class=\"kw-ttt\">traitement d’épreuve</span> par nitro-imidazolé (<span class=\"kw-ttt\">métronidazole</span>)</li><li>3. Si échec : <span class=\"kw-imagerie\">coloscopie</span> parfois nécessaire</li></ul><p><strong><span class=\"kw-etio\">Fièvre typhoïde</span></strong></p><ul><li><span class=\"kw-ttt\">C3G parentérale</span> en probabiliste, puis adaptation à l’<span class=\"kw-bio\">antibiogramme</span> (<span class=\"kw-ttt\">fluoroquinolone</span>, <span class=\"kw-ttt\">C3G parentérale</span> ou <span class=\"kw-ttt\">azithromycine</span>) ; <span class=\"kw-alerte\">déclaration obligatoire</span></li></ul><p><strong><span class=\"kw-etio\">Schistosomose</span></strong></p><ul><li><span class=\"kw-ttt\">Praziquantel</span></li></ul><p><strong><span class=\"kw-etio\">Amoebose hépatique</span></strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> (nitro-imidazolé)</li></ul><p><strong><span class=\"kw-etio\">Arboviroses</span> (dengue, chikungunya, zika)</strong></p><ul><li>Traitement <strong>uniquement symptomatique</strong></li></ul>","suivi":"<p><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-etio\">fièvre typhoïde</span> ; <span class=\"kw-etio\">dengue</span> et <span class=\"kw-etio\">chikungunya</span> diagnostiqués en France métropolitaine (<span class=\"kw-def\">surveillance</span> des cas autochtones, vecteur <em>Aedes</em> répandu de <span class=\"kw-chiffre\">mai à octobre</span> dans le Sud-Est).<br><strong><span class=\"kw-etio\">Fièvre hémorragique virale</span> :</strong> <span class=\"kw-def\">signalement</span> et <span class=\"kw-def\">suivi</span> guidés par le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span>.<br><strong><span class=\"kw-etio\">Turista</span> :</strong> guérison spontanée en <span class=\"kw-chiffre\">3-5 jours</span> ; surveiller l’hydratation (<span class=\"kw-ttt\">SRO</span> chez l’enfant).<br><strong><span class=\"kw-etio\">Schistosomose</span> (phase d’état) :</strong> recherche d’œufs sur <span class=\"kw-clinique\">urines 3 jours de suite</span>, <span class=\"kw-clinique\">selles</span> et <span class=\"kw-clinique\">biopsies endoscopiques</span> (vessie, rectum).<br><strong><span class=\"kw-etio\">Paludisme</span> :</strong> surveillance parasitologique et clinique — <em>cf. item 170</em>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-175.pdf","label":"Collège Pilly — Voyage pays tropical (item 175, PDF)"},{"href":"https://www.hypocampus.fr/home/#/book/5525/chaptergroup/914279?chapter=48474","label":"Hypocampus — Voyage tropical"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Fièvre au retour des tropiques — Réflexe n°1 : frottis + goutte épaisse + TDR sans délai — toute fièvre = paludisme à P. falciparum jusqu’à preuve du contraire","detail":"<h4>CAT — <span class=\"kw-clinique\">Fièvre</span> au retour des tropiques — Démarche diagnostique : éliminer en <span class=\"kw-alerte\">urgence</span> un <span class=\"kw-clinique\">paludisme</span> à P. falciparum</h4>","branches":[{"to":"t-palu","label":"Frottis-GE / TDR POSITIF","color":"red"},{"to":"q-syndrome","label":"Frottis-GE / TDR NÉGATIF — orienter selon le syndrome","color":"amber"}]},{"id":"t-palu","kind":"terminal","label":"Paludisme à P. falciparum","color":"red","detail":"<h4>Clinique</h4><ul><li>Troubles <span class=\"kw-clinique\">digestifs</span> et <span class=\"kw-clinique\">neurologiques</span> ; <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">hépatomégalie</span> ; contamination par l’<span class=\"kw-etio\">anophèle</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Thrombopénie</span> ++, <span class=\"kw-bio\">anémie</span>, <span class=\"kw-bio\">leucopénie</span> ; <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">ALAT</span> &lt; 5N. Confirmation : <span class=\"kw-bio\">goutte épaisse</span> + <span class=\"kw-bio\">frottis mince</span>, <span class=\"kw-bio\">TDR</span>, <span class=\"kw-bio\">biologie moléculaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence diagnostique ET thérapeutique</span> — 1ʳᵉ cause devant toute <span class=\"kw-clinique\">fièvre</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant le retour</li><li>Recherche des <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> et traitement spécifique : <em>cf. item 170 (<span class=\"kw-clinique\">Paludisme</span>)</em></li></ul>"},{"id":"q-syndrome","kind":"decision","label":"Syndrome dominant après élimination du paludisme — Orientation selon les signes, la durée d’incubation et l’exposition","branches":[{"to":"q-fhv","label":"Fièvre + signes hémorragiques","color":"red"},{"to":"q-diarrhee","label":"Diarrhée fébrile / troubles digestifs","color":"amber"},{"to":"q-incub","label":"Autre orientation : incubation / exposition","color":"blue"}]},{"id":"q-fhv","kind":"decision","label":"Retour de zone à risque de fièvre hémorragique virale ?","branches":[{"to":"t-fhv","label":"OUI — suspicion de FHV","color":"red"},{"to":"t-hemorr","label":"NON — autres causes de fièvre hémorragique","color":"amber"}]},{"id":"t-fhv","kind":"terminal","label":"Fièvre hémorragique virale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Ebola</span>, <span class=\"kw-etio\">Marburg</span>, <span class=\"kw-etio\">Lassa</span> — <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-alerte\">syndrome hémorragique</span> au retour d’une zone à risque</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Isolement et signalement immédiats</span></li><li><span class=\"kw-ttt\">Précautions complémentaires</span> renforcées pour la protection du patient ET du personnel</li><li>Prise en charge guidée par le <span class=\"kw-def\">CNR des fièvres hémorragiques virales</span> et <span class=\"kw-def\">Santé publique France</span> — <span class=\"kw-clinique\">les</span> contacter <strong>avant tout prélèvement</strong></li></ul><h4>Pièges</h4><ul><li>Ebola, Marburg et Lassa ne sont <strong>pas</strong> des <span class=\"kw-etio\">arboviroses</span></li></ul>"},{"id":"t-hemorr","kind":"terminal","label":"Autres fièvres avec signes hémorragiques","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Paludisme</span> (à réitérer si forte présomption)</li><li><span class=\"kw-etio\">Hépatite</span> fulminante</li><li><span class=\"kw-etio\">Leptospirose</span> ictéro-<span class=\"kw-etio\">hémorragique</span></li><li><span class=\"kw-etio\">Dengue</span> et autres <span class=\"kw-etio\">arboviroses</span> hémorragiques (<span class=\"kw-etio\">fièvre jaune</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> et <span class=\"kw-def\">surveillance</span> ; la <span class=\"kw-etio\">fièvre jaune</span> expose à une <span class=\"kw-alerte\">insuffisance hépatocellulaire et rénale</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">20 %</span>)</li></ul>"},{"id":"q-diarrhee","kind":"decision","label":"Turista banale ou infection systémique ?","branches":[{"to":"t-turista","label":"Diarrhée aiguë banale","color":"green"},{"to":"t-typhoide","label":"Syndrome typhoïdique","color":"amber"}]},{"id":"t-turista","kind":"terminal","label":"Diarrhée du voyageur (turista)","color":"green","detail":"<h4>Clinique</h4><ul><li>Survient souvent la <span class=\"kw-chiffre\">1ʳᵉ semaine</span> du séjour ; guérison spontanée en <span class=\"kw-chiffre\">3-5 jours</span> ; germe principal <span class=\"kw-etio\">E. coli entérotoxinogène</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Réhydratation</span> dans tous <span class=\"kw-clinique\">les</span> cas (<span class=\"kw-ttt\">SRO</span> chez l’enfant)</li><li><span class=\"kw-ttt\">Racécadotril</span> si nécessaire</li><li><span class=\"kw-ttt\">Antibiothérapie</span> non recommandée en routine</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-ttt\">Azithromycine</span> en 1ʳᵉ intention (ou <span class=\"kw-ttt\">ciprofloxacine</span>), <span class=\"kw-chiffre\">1 à 5 jours</span> — seulement si <span class=\"kw-clinique\">diarrhée</span> invasive ou cholériforme intense persistant <span class=\"kw-chiffre\">&gt; 48 h</span> sans recours possible aux soins locaux</li></ul>"},{"id":"t-typhoide","kind":"terminal","label":"Fièvre typhoïde","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées</span>, insomnie, <span class=\"kw-clinique\">pouls dissocié</span>, <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">tuphos</span>, <span class=\"kw-clinique\">diarrhée « jus de melon »</span> ; transmission oro-fécale, réservoir strictement humain</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Leuco-neutropénie</span>, <span class=\"kw-bio\">CRP</span> élevée ; confirmation par <span class=\"kw-bio\">hémocultures</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">C3G parentérale</span> en probabiliste, puis adaptation à l’<span class=\"kw-bio\">antibiogramme</span> (<span class=\"kw-ttt\">fluoroquinolone</span>, <span class=\"kw-ttt\">C3G parentérale</span> ou <span class=\"kw-ttt\">azithromycine</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Maladie à déclaration obligatoire</span> ; complications : <span class=\"kw-alerte\">hémorragies</span> et <span class=\"kw-alerte\">perforations digestives</span></li></ul>"},{"id":"q-incub","kind":"decision","label":"Durée d’incubation et exposition","branches":[{"to":"t-arbo","label":"Incubation brève / piqûre Aedes","color":"blue"},{"to":"t-schisto","label":"Baignade en eau douce + hyperéosinophilie","color":"blue"},{"to":"t-amoebose","label":"Hépatomégalie douloureuse / incubation longue","color":"blue"}]},{"id":"t-arbo","kind":"terminal","label":"Arbovirose (dengue ++)","color":"blue","detail":"<h4>Clinique</h4><ul><li>2ᵉ étiologie la plus fréquente après le <span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">rash</span>, <span class=\"kw-clinique\">splénomégalie</span> ; contamination par l’<span class=\"kw-etio\">Aedes</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Leucopénie</span> ++, <span class=\"kw-bio\">thrombopénie</span> ++, <span class=\"kw-bio\">CRP</span> basse, <span class=\"kw-bio\">ALAT</span> &lt; 5N ; <span class=\"kw-bio\">PCR</span> durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premiers jours</span> de <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-bio\">sérologie</span> au-delà</li></ul><h4>Traitement</h4><ul><li>Uniquement <strong>symptomatique</strong> ; <span class=\"kw-alerte\">déclaration obligatoire</span> en métropole (<span class=\"kw-etio\">dengue</span>, <span class=\"kw-etio\">chikungunya</span>)</li></ul>"},{"id":"t-schisto","kind":"terminal","label":"Schistosomose (phase d’invasion)","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Prurit</span>, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">hépatomégalie</span>, <span class=\"kw-clinique\">toux</span> ; contamination par <span class=\"kw-def\">contact</span> cutané avec une <span class=\"kw-etio\">eau douce</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie</span>, <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-bio\">sérologie</span> en phase d’invasion, recherche d’œufs (<span class=\"kw-clinique\">selles</span>, <span class=\"kw-clinique\">urines</span>) en phase d’état</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Praziquantel</span></li></ul>"},{"id":"t-amoebose","kind":"terminal","label":"Amoebose hépatique","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Hépatomégalie douloureuse</span> fébrile ; transmission oro-fécale</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperleucocytose à PNN</span>, <span class=\"kw-bio\">CRP</span> élevée ; <span class=\"kw-imagerie\">échographie</span> hépatique ± <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-bio\">sérologie</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> (nitro-imidazolé)</li></ul><h4>Pièges</h4><ul><li>L’amoebose <strong>intestinale aiguë</strong> ne donne <strong>pas</strong> de <span class=\"kw-clinique\">fièvre</span> — seule l’amoebose <strong>hépatique</strong> est fébrile</li></ul>"}]},"cards":[{"i":"18f5e9359f33","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles sont les caractéristiques du voyageur à considérer pour l'évaluation du risque sanitaire ?","a":"<ul><li>L'<strong>âge</strong>.</li><li>L'état de <strong>grossesse</strong>.</li><li>Les <strong>comorbidités</strong> existantes.</li><li>Le <strong>statut immunitaire et vaccinal</strong>.</li><li>Le <strong>budget</strong>, qui peut influencer l'accès aux vaccins et chimioprophylaxies non remboursés.</li></ul>"},{"i":"7df5276cd888","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels sont les trois paramètres essentiels à analyser systématiquement pour évaluer le risque sanitaire individuel avant un voyage international ?","a":"<p>L'évaluation repose sur le croisement de trois paramètres : la <strong>destination</strong>, les <strong>modalités du voyage</strong> et les caractéristiques du <strong>voyageur</strong>.</p>"},{"i":"98645b1fba77","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels facteurs liés à la destination doivent être pris en compte lors de l'évaluation du risque sanitaire pré-voyage ?","a":"<ul><li>La <strong>situation sanitaire et politique</strong> du pays.</li><li>La <strong>saison</strong> du voyage.</li><li>Les <strong>zones spécifiques visitées</strong> (rurales ou urbaines).</li></ul>"},{"i":"ab99a29ac68f","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles sont les principales sources numériques officielles d'information pour les recommandations aux voyageurs en France ?","a":"<p>Les recommandations sont émises par le <strong>Comité des maladies liées aux voyages et des maladies d'importation (CMVI) du HCSP</strong> et sont publiées dans le <strong>Bulletin épidémiologique hebdomadaire (BEH)</strong>. Elles sont actualisées en fonction de la situation internationale.</p>"},{"i":"ce5b23b0bd56","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quelles populations sont considérées spécifiquement à risque pour les voyages internationaux ?","a":"<ul><li>Les <strong>adultes jeunes</strong> effectuant des voyages non organisés de plusieurs semaines vers des destinations telles que l'Afrique subsaharienne ou l'Inde.</li><li>Les <strong>sujets émigrés</strong> retournant dans leur pays d'origine.</li><li>Les <strong>immunodéprimés</strong>.</li></ul>"},{"i":"e711d439361e","n":175,"o":"175-1","u":"Définition","t":"Connaître les populations, destinations et situations à risque dans le cadre des voyages, connaître les sources numériques d’information","q":"Quels éléments liés aux modalités du voyage sont importants pour l'évaluation du risque sanitaire individuel ?","a":"<ul><li>Le <strong>moyen de transport</strong>.</li><li>Les <strong>conditions de logement</strong>.</li><li>Les <strong>activités prévues</strong> (baignade, randonnée).</li><li>Le type de voyage (organisé ou aventureux).</li><li>La <strong>durée du séjour</strong>, car une exposition ponctuelle suffit pour le paludisme, la fièvre jaune et la dengue.</li></ul>"},{"i":"89a5a7bdf4bc","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les causes médicamenteuses des diarrhées d'importation ?","a":"<p>Les causes médicamenteuses des diarrhées d'importation sont :</p><ul><li>Les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens).</li><li>Certains <strong>antipaludiques</strong> comme l'<strong>atovaquone-proguanil</strong> et la <strong>chloroquine-proguanil</strong>.</li></ul>"},{"i":"9ca1f702462b","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quels pièges diagnostiques concernant le paludisme et l'amibiase faut-il connaître face à une diarrhée d'importation ?","a":"<p>Il faut connaître les pièges diagnostiques suivants :</p><ul><li>Le <strong>paludisme</strong> peut se présenter comme une <strong>diarrhée non fébrile atypique</strong>.</li><li>L'<strong>amoebose intestinale aiguë</strong> ne donne <strong>pas de fièvre</strong>, alors que l'amoebose hépatique, en revanche, peut s'accompagner de diarrhées fébriles.</li></ul>"},{"i":"bf548ed53aa0","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les principales étiologies des diarrhées d'importation non fébriles, souvent subaiguës ?","a":"<p>Les principales étiologies des diarrhées d'importation non fébriles, souvent subaiguës, incluent :</p><ul><li>Le <strong>paludisme</strong> (10 % de présentations atypiques).</li><li>Le <strong>choléra</strong>.</li><li>Les <strong>helminthoses intestinales</strong> (orientées par l'hyperéosinophilie).</li><li>Les <strong>protozooses</strong> : <ul><li>La <strong>giardose</strong> (cause la plus fréquente de diarrhée prolongée non fébrile au retour des tropiques).</li><li>L'<strong>amoebose intestinale aiguë</strong>.</li><li>La <strong>cyclosporose</strong>.</li></ul></li></ul>"},{"i":"bfd10126c79c","n":175,"o":"175-14","u":"Étiologies","t":"Connaître les principales étiologies des diarrhées d’importation","q":"Quelles sont les principales étiologies des diarrhées d'importation fébriles ?","a":"<p>Les principales étiologies des diarrhées d'importation fébriles, souvent aiguës, incluent :</p><ul><li>La <strong>turista</strong>.</li><li>Le <strong>paludisme</strong> (à évoquer en premier, surtout chez l'enfant).</li><li>Les infections bactériennes avec syndrome dysentérique : <strong>shigellose</strong>, <strong>salmonelloses</strong>, <strong>Campylobacter</strong> (nécessite une coproculture).</li><li>La <strong>primo-infection VIH</strong>.</li><li>Les <strong>hépatites A et E</strong>.</li><li>L'infection à <strong>Clostridioides difficile</strong> en cas d'antibiothérapie récente.</li></ul>"},{"i":"21ead1429873","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est la prise en charge initiale d'une diarrhée du voyageur ?","a":"<ul><li>La <strong>réhydratation</strong> est essentielle dans tous les cas, avec des Sels de Réhydratation Orale (SRO) chez l'enfant.</li><li>Le <strong>racécadotril</strong> (antidiarrhéique antisécrétoire) peut être utilisé si nécessaire.</li><li>L'antibiothérapie n'est <strong>pas recommandée en routine</strong>.</li></ul>"},{"i":"78441fc63ab4","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est la démarche diagnostique devant une suspicion de protozoose (diarrhée prolongée) au retour d'un voyage ?","a":"<ul><li>Réaliser un <strong>examen parasitologique des selles</strong>.</li><li>Si celui-ci est difficile, un <strong>traitement d'épreuve par nitro-imidazolé (métronidazole)</strong> peut être envisagé.</li><li>En cas d'échec de ce traitement, une <strong>coloscopie</strong> peut parfois être nécessaire.</li></ul>"},{"i":"8218f240cfc4","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Dans quels cas une antibiothérapie est-elle indiquée pour la diarrhée du voyageur et quel est le traitement de première intention ?","a":"<p>Une antibiothérapie est indiquée uniquement en cas de <strong>diarrhée invasive</strong>, ou de <strong>diarrhée cholériforme intense persistant plus de 48 heures</strong> sans accès aux soins locaux. Le traitement de première intention est l'<strong>azithromycine</strong> (ou la ciprofloxacine) pendant 1 à 5 jours.</p>"},{"i":"d281d0bd46b2","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quels sont les agents infectieux majoritaires responsables de la diarrhée du voyageur ?","a":"<ul><li>Les <strong>bactéries</strong> (environ 50%), principalement E. coli entérotoxinogène (ETEC).</li><li>Les <strong>virus</strong> (5-25%), notamment les norovirus.</li><li>Les <strong>parasites</strong> (moins de 10%), principalement les protozoaires et les amibes.</li></ul>"},{"i":"f12832817d4f","n":175,"o":"175-15","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de diarrhée au retour du voyage","q":"Quelle est l'étiologie bactérienne la plus fréquente de la diarrhée du voyageur ?","a":"<p>La bactérie la plus fréquemment impliquée dans la diarrhée du voyageur est <strong>E. coli entérotoxinogène (ETEC)</strong>.</p>"},{"i":"07a15c2cb942","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quels sont les éléments essentiels à inclure dans la trousse de médicaments du voyageur en pays tropical ?","a":"<ul><li>Un <strong>antalgique/antipyrétique</strong> (paracétamol).</li><li>Un <strong>antidiarrhéique</strong> (racécadotril).</li><li>Un <strong>antiémétique</strong>.</li><li>Un <strong>antibiotique</strong> (si absence de soins locaux).</li><li>Un <strong>anti-H1</strong> de dernière génération.</li><li>Un <strong>antipaludique préventif</strong> si nécessaire.</li></ul>"},{"i":"4e9667caa565","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Comment la gestion des maladies chroniques doit-elle être abordée avant un voyage dans un pays tropical ?","a":"<p>Avant un voyage, il est primordial de procéder à une <strong>évaluation médicale</strong> complète de la maladie chronique. Il faut emporter tous les <strong>documents médicaux</strong> pertinents, idéalement traduits en anglais. Dans certains cas, le voyage peut être <strong>contre-indiqué</strong> en fonction de la pathologie chronique.</p>"},{"i":"51441922c887","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les mesures de prévention solaire et de baignade recommandées lors d'un voyage en pays tropical ?","a":"<ul><li><strong>Pas d'exposition solaire avant 1 an</strong> chez l'enfant.</li><li>Utilisation d'une <strong>crème solaire FPS ≥ 30</strong>, réappliquée toutes les <strong>2 heures</strong>.</li><li>Port de <strong>lunettes de soleil enveloppantes</strong> à verres filtrants CE 3 ou 4.</li><li><strong>Éviter la baignade en eau douce stagnante</strong> pour prévenir la schistosomose et la leptospirose.</li><li><strong>Ne pas marcher pieds nus</strong> en extérieur pour éviter l'anguillulose et l'ankylostomose.</li></ul>"},{"i":"6e096447db3f","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les molécules de chimioprophylaxie antipaludique recommandées pour l'Afrique subsaharienne et leurs spécificités ?","a":"<ul><li><strong>Atovaquone-proguanil</strong> : prise quotidienne <strong>pendant le séjour</strong> et <strong>1 semaine après le retour</strong> (agit sur les formes hépatiques). Utilisable dès <strong>≥ 11 kg</strong>.</li><li><strong>Méfloquine</strong> : début <strong>10 jours avant</strong> le départ, prise <strong>hebdomadaire</strong>, poursuivie <strong>3 semaines après le retour</strong> (nécessite un test de tolérance). Utilisable dès <strong>≥ 15 kg</strong>. Contre-indications : antécédents de dépression ou de convulsions, prise de valproate de sodium.</li><li><strong>Doxycycline</strong> : prise quotidienne <strong>pendant le séjour</strong> et <strong>4 semaines après le retour</strong>. Utilisable dès <strong>≥ 8 ans</strong>.</li></ul>"},{"i":"867dcfa670f5","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quels sont les principaux vecteurs et les maladies associées à la piqûre d'arthropodes dans les régions tropicales ?","a":"<ul><li>L'<strong>Anophèle</strong> (pique la nuit) transmet le <strong>paludisme</strong>.</li><li>Le <strong>Culex</strong> (pique la nuit) transmet les rickettsioses, borrélioses et encéphalites à tiques.</li><li>L'<strong>Aedes</strong> (pique le jour) transmet la <strong>dengue</strong>, le <strong>Zika</strong>, le <strong>chikungunya</strong> et la <strong>fièvre jaune</strong>.</li></ul>"},{"i":"f02d15ca6f72","n":175,"o":"175-2","u":"Prise en charge","t":"Connaître les principales mesures préventives avant un voyage : gestion des maladies chroniques, hygiène dont alimentaire, prévention anti-vectorielle, prévention sexuelle, baignade, soleil, trousse du voyageur","q":"Quelles sont les mesures d'hygiène alimentaire essentielles pour prévenir les maladies à transmission oro-fécale en voyage tropical ?","a":"<ul><li><strong>Lavage des mains</strong> fréquent (eau et savon ou SHA).</li><li>Consommation d'<strong>eau en bouteille encapsulée</strong>, ou rendue potable (filtration, ébullition, désinfectant).</li><li>Consommation de lait <strong>pasteurisé ou bouilli</strong> et de viandes/poissons <strong>bien cuits et consommés chauds</strong>.</li><li><strong>Peler les fruits</strong> soi-même.</li><li><strong>Éviter les crudités</strong>, les fruits de mer crus, les buffets froids, les glaçons et les glaces.</li><li>Se méfier de la <strong>ciguatera</strong> (gros poissons de mer).</li></ul>"},{"i":"0aa43ff53aaa","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quels sont les enjeux spécifiques pour le jeune enfant et le nourrisson lors d'un voyage en pays tropical ?","a":"<p>Chez le jeune enfant et le nourrisson, la <strong>barrière hémato-encéphalique (BHE)</strong> est immature, ce qui contre-indique l'usage de <strong>répulsifs cutanés avant 6 mois</strong>. L'<strong>exposition solaire est déconseillée avant 1 an</strong> et certains vaccins sont soumis à un âge minimal.</p>"},{"i":"4afec477f036","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quelles précautions spécifiques doivent être prises lors d'un voyage en pays tropical pour une femme enceinte ?","a":"<p>Pour une femme enceinte, le <strong>vaccin anti-amarile est déconseillé</strong>. Le <strong>paludisme</strong> est volontiers plus grave et certains <strong>antipaludiques et répulsifs</strong> peuvent être limités ou contre-indiqués. Une évaluation renforcée est donc essentielle.</p>"},{"i":"a965370c45fa","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quels sont les profils de voyageurs considérés comme fragiles nécessitant une évaluation pré-voyage renforcée ?","a":"<p>Les profils de voyageurs considérés comme particulièrement fragiles sont :</p><ul><li>Les <strong>immunodéprimés</strong>.</li><li>Les <strong>femmes enceintes</strong>.</li><li>Les <strong>jeunes enfants</strong> / <strong>nourrissons</strong>.</li><li>Les <strong>sujets âgés</strong>.</li><li>Les personnes atteintes de <strong>maladie chronique</strong>.</li><li>Les <strong>sujets émigrés retournant au pays d'origine</strong>.</li></ul>"},{"i":"ca65826b306a","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Quelles sont les spécificités et les précautions à prendre concernant la vaccination chez le voyageur immunodéprimé ?","a":"<p>Chez le voyageur immunodéprimé, les <strong>vaccins vivants atténués sont contre-indiqués</strong>. Cependant, le <strong>vaccin anti-amarile</strong> (fièvre jaune) peut être envisagé chez les patients VIH si les <strong>CD4 sont supérieurs à 200/mm³ et à 15% des lymphocytes</strong>. Ces patients ont un <strong>risque infectieux majoré</strong>.</p>"},{"i":"e5a0c58b5b05","n":175,"o":"175-3","u":"Prise en charge","t":"Identifier les personnes avec une fragilité particulière","q":"Pourquoi les sujets émigrés retournant dans leur pays d'origine représentent-ils un profil de risque particulier lors d'un voyage en pays tropical ?","a":"<p>Les sujets émigrés retournant au pays d'origine présentent un risque particulier en raison de leur <strong>moindre recours à la prévention</strong>, d'une <strong>perte d'immunité</strong> au fil du temps, et de séjours souvent <strong>longs</strong> dans des <strong>zones rurales</strong> à plus haut risque d'exposition.</p>"},{"i":"5d17aa833009","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quelles sont les caractéristiques du vaccin contre la fièvre jaune (anti-amarile), y compris ses contre-indications et son statut obligatoire ?","a":"<p>Le vaccin contre la fièvre jaune est un vaccin <strong>vivant atténué</strong>. Ses caractéristiques sont :</p><ul><li><strong>Contre-indications</strong> : Déconseillé pendant la <strong>grossesse</strong> et chez l'<strong>immunodéprimé</strong> (possible dans le VIH si <strong>CD4 &gt; 200/mm³</strong> et <strong>&gt; 15 % de lymphocytes</strong>).</li><li><strong>Obligatoire ou recommandé</strong> pour l'<strong>Afrique intertropicale</strong> et la <strong>région amazonienne</strong>, absent en Asie et en Océanie.</li><li>Authentifié par un médecin d'un <strong>Centre agréé de Vaccinations Internationales</strong> sur le carnet international.</li><li>Efficace <strong>10 jours après l'injection</strong> et pour <strong>toute la vie</strong> (sauf injection avant 2 ans ou pendant la grossesse où un rappel pourrait être envisagé).</li></ul>"},{"i":"9e9bad7661d4","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quels sont les vaccins recommandés pour le voyageur selon les indications géographiques ou les conditions de séjour ?","a":"<p>Les vaccins recommandés et leurs indications sont :</p><ul><li><strong>Hépatite B</strong> : Séjour fréquent ou prolongé en zone d'endémie.</li><li><strong>Hépatite A</strong> (dès <strong>1 an</strong>) : Séjour en pays à hygiène précaire.</li><li><strong>Typhoïde</strong> (dès <strong>2 ans</strong>, rappel tous les <strong>3 ans</strong>) : Séjours prolongés en pays à bas niveau d'hygiène (sous-continent indien ++).</li><li><strong>Rage</strong> (dès l'âge de la marche) : Séjour prolongé, aventureux ou isolé en zone à risque (Asie, Afrique, Amérique du Sud).</li><li><strong>Méningocoque ACYW conjugué</strong> (dès <strong>1 an</strong> pour l'enfant voyageur) : Ceinture de la méningite en Afrique en saison sèche (<strong>novembre-juin</strong>) et contact étroit et prolongé avec la population.</li></ul>"},{"i":"e16a240cf3d6","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quels sont les vaccins de routine à considérer chez l'enfant non vacciné avant un séjour prolongé en pays de forte endémie ?","a":"<p>Pour un enfant non vacciné, en cas de séjour prolongé (<strong>&gt; 1 mois</strong>) en pays de forte endémie, il convient de considérer :</p><ul><li>Le <strong>BCG</strong>.</li><li>Le vaccin <strong>anti-rougeoleux</strong> (dès <strong>6 mois</strong>, vaccin monovalent).</li><li>Le vaccin contre l'<strong>hépatite B</strong>.</li></ul>"},{"i":"e62b588fd499","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"À partir de quel âge les enfants peuvent-ils recevoir les vaccins contre la Fièvre jaune, l'Hépatite A, la Typhoïde et la Rage, et quelles sont les régions concernées pour chacun ?","a":"<p>Les âges minimaux et les régions concernées pour les vaccins spécifiques aux enfants voyageurs sont :</p><ul><li><strong>Fièvre jaune</strong> : <strong>9 mois</strong> (<strong>6 mois si épidémie</strong>) pour les régions intertropicales d'Afrique et d'Amérique du Sud.</li><li><strong>Hépatite A</strong> : <strong>1 an</strong> pour toutes destinations tropicales ou peu hygiéniques.</li><li><strong>Typhoïde</strong> : <strong>2 ans</strong> pour le sous-continent indien, l'Asie du Sud-Est, l'Afrique.</li><li><strong>Rage</strong> : Dès l'<strong>âge de la marche</strong> pour l'Asie, l'Amérique du Sud, l'Afrique en cas de séjour isolé ou prolongé.</li></ul>"},{"i":"f1c340cefe6d","n":175,"o":"175-5","u":"Prise en charge","t":"Connaître les vaccinations spécifiques du voyageur","q":"Quelles sont les trois catégories de vaccinations à considérer pour le voyageur, selon les recommandations médicales ?","a":"<p>La vaccination du voyageur s'organise en trois catégories :</p><ul><li>Mise à jour des <strong>vaccins de routine</strong>.</li><li>Vaccins <strong>obligatoires</strong>.</li><li>Vaccins <strong>recommandés</strong>.</li></ul>"},{"i":"1e511d4a0f58","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les éléments clinico-biologiques évocateurs d'une arbovirose (notamment la dengue) au retour d'une zone tropicale ?","a":"<p>Les éléments évocateurs d'une arbovirose sont :</p><ul><li>Des <strong>myalgies</strong>, <strong>arthralgies</strong></li><li>Un <strong>rash</strong>, une splénomégalie</li><li>Une <strong>leucopénie</strong> ++ et une <strong>thrombopénie</strong> ++</li><li>Une CRP basse</li><li>Des ALAT &lt; 5N</li></ul>"},{"i":"41c752df0e29","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les signes clinico-biologiques en faveur d'une hépatite virale d'importation (type A) au retour d'une zone tropicale ?","a":"<p>Une hépatite virale se manifeste par :</p><ul><li>Des <strong>troubles digestifs</strong>, un <strong>ictère</strong></li><li>Une hépatomégalie, un urticaire</li><li>Une leucopénie, une CRP basse</li><li>Des <strong>ALAT &gt; 10N</strong></li></ul>"},{"i":"809fd1fe46b8","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quelles sont les manifestations cliniques et biologiques d'une schistosomose en phase d'invasion après une exposition en zone tropicale ?","a":"<p>En phase d'invasion, la schistosomose peut présenter :</p><ul><li>Un <strong>prurit</strong>, un urticaire, des arthralgies</li><li>Une hépatomégalie, une toux</li><li>Une <strong>hyperéosinophilie</strong></li><li>Une CRP élevée</li></ul>"},{"i":"955deb05d1ee","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les signes cliniques et biologiques évocateurs d'une fièvre typhoïde après un voyage en région tropicale ?","a":"<p>La fièvre typhoïde se caractérise par :</p><ul><li>Des <strong>céphalées</strong> ++, une insomnie</li><li>Un <strong>pouls dissocié</strong> (fièvre haute et bradycardie relative)</li><li>Une splénomégalie</li><li>Une leucopénie, une CRP élevée</li><li>Des ALAT &lt; 5N</li></ul>"},{"i":"c18ca875fc35","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Comment s'oriente le diagnostic d'une rickettsiose ou d'une amœbose hépatique devant une fièvre au retour des tropiques ?","a":"<ul><li>Pour une <strong>rickettsiose</strong> : il faut rechercher une <strong>escarre d'inoculation</strong>, une éruption, des adénopathies, des céphalées, associés à une leucopénie, une thrombopénie et une CRP élevée.</li><li>Pour une <strong>amœbose hépatique</strong> : elle se manifeste par une <strong>hépatomégalie douloureuse</strong> avec une hyperleucocytose à PNN et une CRP élevée.</li></ul>"},{"i":"dbab71ac66e0","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quelle est la première étiologie à évoquer devant toute fièvre survenant dans les 3 mois suivant un retour de zone d'endémie tropicale ?","a":"<p>La première étiologie à évoquer est le <strong>paludisme à <em>P. falciparum</em></strong>.</p>"},{"i":"f313147f9f30","n":175,"o":"175-8","u":"Diagnostic positif","t":"Connaître les principales maladies d’importation responsables de fièvre","q":"Quels sont les principaux tableaux clinico-biologiques suggestifs d'un paludisme au retour d'une zone tropicale ?","a":"<p>Devant un paludisme, l'orientation clinico-biologique comprend :</p><ul><li>Des <strong>troubles digestifs et neurologiques</strong></li><li>Une <strong>splénomégalie</strong>, une hépatomégalie</li><li>Une <strong>thrombopénie</strong> ++</li><li>Une anémie, une leucopénie</li><li>Une CRP élevée</li><li>Des ALAT &lt; 5N</li></ul>"},{"i":"05562f702729","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"En cas de fièvre au retour des tropiques, quelles autres causes, infectieuses ou non infectieuses, doit-on également élargir le diagnostic ?","a":"<p>Il est important de penser aux causes <strong>non infectieuses</strong> comme la <strong>MTEV (Maladie Thromboembolique Veineuse)</strong>, une <strong>néoplasie</strong> ou une <strong>maladie inflammatoire</strong>. Il faut également considérer les causes <strong>infectieuses cosmopolites</strong> telles qu'une <strong>PNA (Pyélonéphrite Aiguë)</strong>, la <strong>grippe</strong> ou une <strong>pneumopathie</strong>.</p>"},{"i":"41e6cfcd02c4","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire d'un patient présentant de la fièvre au retour d'un voyage en zone tropicale ?","a":"<ul><li><strong>Destination précise</strong> et <strong>dates du séjour</strong>.</li><li>Durée d'incubation.</li><li>Prise ou non d'une <strong>chimioprophylaxie antipaludique</strong>.</li><li>Statut vaccinal.</li><li><strong>Activités à risque</strong> (baignade, contact animal, rapports sexuels non protégés).</li></ul>"},{"i":"7d6c79454104","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quelle est l'attitude initiale systématique devant toute fièvre au retour d'un voyage en zone tropicale ?","a":"<p>Devant toute fièvre au retour d'un voyage en zone tropicale, l'urgence est d'éliminer un <strong>paludisme</strong>. Toute fièvre au retour des tropiques est un paludisme jusqu'à preuve du contraire.</p>"},{"i":"e84ef2fead9e","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quels examens complémentaires sont prioritaires pour éliminer un paludisme à P. falciparum devant une fièvre au retour des tropiques ?","a":"<p>Il est impératif de réaliser sans délai un <strong>frottis-goutte épaisse</strong> et un <strong>TDR (Test de Diagnostic Rapide)</strong>. C'est une urgence diagnostique et thérapeutique. Le frottis-goutte épaisse prime sur tout autre examen dans ce contexte.</p>"},{"i":"fae225805915","n":175,"o":"175-9","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de fièvre au retour du voyage","q":"Quel bilan biologique complémentaire doit être réalisé en cas de fièvre au retour des tropiques, en l'absence d'orientation diagnostique évidente après le bilan initial ?","a":"<ul><li><strong>NFS</strong> (Numération Formule Sanguine).</li><li><strong>CRP</strong> (Protéine C Réactive).</li><li><strong>Transaminases</strong>.</li><li><strong>Hémocultures</strong>.</li><li><strong>Sérologies</strong> orientées par la clinique.</li></ul>"}]};